window.DEEPDIVE=window.DEEPDIVE||{};window.DEEPDIVE["uncertainty-calibration"]={"title":"不确定性与校准：让“80% 把握”真的约等于 80% 正确","subtitle":"从置信分数、可靠性图和 ECE，到选择性预测、拒答阈值与分布漂移。","thesis":"校准不要求每个样本都知道自己是否正确，而要求在同类、同分数的一组案例中，声称 80% 置信的案例长期约有 80% 正确。它是<b>分数与经验风险之间的映射</b>，不是语言流畅度，也不是消除错误；一旦任务、切片或分布变化，校准证据就可能失效。","quality":{"contractVersion":2,"examples":[{"section":4,"evidence":{"setup":"十笔退款的分数和正确标签","rule":"计算规则是每桶的 |准确率−平均置信| 乘该桶样本占比","steps":"低桶贡献 0.010，中桶 0.040，高桶 0.070","interpretation":"高桶平均置信 0.90 却只正确 2/3"}}],"formulas":[{"id":"calibration-ece","section":3,"formulaIndex":1,"symbols":[{"name":"ECE","meaning":"各置信分桶加权后的平均校准差距","evidence":"输出可靠性图与期望校准误差 ECE"},{"name":"m","meaning":"当前置信度分桶的编号","evidence":"分桶 Bm"},{"name":"B","meaning":"落入同一置信范围的预测样本集合","evidence":"分桶 Bm"},{"name":"n","meaning":"参与校准评估的预测样本总数","evidence":"输入 n 个预测"},{"name":"acc","meaning":"某个置信分桶内的实际正确比例","evidence":"实际准确率 acc(Bm)"},{"name":"conf","meaning":"某个置信分桶内的平均模型分数","evidence":"每桶平均置信 conf(Bm)"}]},{"id":"calibration-decision-cost","section":6,"formulaIndex":1,"symbols":[{"name":"Cost","meaning":"给定阈值策略下三类结果的总期望成本","evidence":"输出自动、转人工或拒绝以及期望成本 Cost(τ)"},{"name":"τ","meaning":"决定样本能否自动处理的校准分数阈值","evidence":"阈值 τ"},{"name":"Cerror","meaning":"一次错误自动处理造成的业务成本","evidence":"错误成本 Cerror"},{"name":"PerrorAuto","meaning":"样本错误且被自动处理的概率","evidence":"三类结果的概率乘成本"},{"name":"Cmanual","meaning":"一次转交人工审核的成本","evidence":"人工成本 Cmanual"},{"name":"Pmanual","meaning":"样本被转交人工的概率","evidence":"输出自动、转人工或拒绝"},{"name":"Creject","meaning":"一次拒绝或延迟服务造成的成本","evidence":"拒绝成本 Creject"},{"name":"Preject","meaning":"样本被系统拒绝处理的概率","evidence":"输出自动、转人工或拒绝"}]}],"termReviews":[{"section":2,"reviewedAt":"2026-07-27","terms":[{"name":"logprob","meaning":"模型为某个 token 给出的对数条件概率","purpose":"构造连续原始分数并分析生成偏好","definitionEvidence":"token 的 logprob","purposeEvidence":"构造原始分数"},{"name":"校准集","meaning":"只用于学习原始分数到经验正确率映射的独立带标签样本","purpose":"避免在训练或最终测试数据上拟合概率解释","definitionEvidence":"独立校准集","purposeEvidence":"学习该分数到任务正确频率的映射"}]},{"section":3,"reviewedAt":"2026-07-27","terms":[{"name":"ECE","meaning":"置信分桶内置信度与准确率差异的加权平均","purpose":"检查概率承诺是否匹配经验频率","definitionEvidence":"期望校准误差 ECE","purposeEvidence":"平均差距越小"},{"name":"Brier","meaning":"预测概率与二元真实标签平方差的平均评分","purpose":"同时惩罚概率偏差和错误结果","definitionEvidence":"Brier 分数","purposeEvidence":"同时惩罚概率偏差和错误"},{"name":"似然","meaning":"模型对已观察标签赋予概率的大小","purpose":"用带标签数据衡量概率预测是否支持真实结果","definitionEvidence":"负对数似然","purposeEvidence":"惩罚更重"},{"name":"对数似然","meaning":"把真实标签概率取对数后汇总的概率评分","purpose":"更强惩罚给错误结果极低概率的过度自信预测","definitionEvidence":"负对数似然","purposeEvidence":"高置信却错误”惩罚更重"}]},{"section":5,"reviewedAt":"2026-07-27","terms":[{"name":"logits","meaning":"softmax 转换前各类别未归一化的模型分数","purpose":"作为温度缩放调整概率尖锐程度的输入","definitionEvidence":"输入分类 logits z","purposeEvidence":"输出 softmax(z/T) 的重标度概率"},{"name":"softmax","meaning":"把各类别实数分数转换成总和为一的概率分布","purpose":"由温度控制分类概率分布的尖锐或平缓程度","definitionEvidence":"softmax(z/T)","purposeEvidence":"软化过度尖锐分布"}]}],"sectionContracts":[{"section":1,"definition":{"answer":"校准要求相同分数组的声称概率匹配经验正确频率。","evidence":"相同分数组的经验正确率是否匹配声称概率"},"problem":{"answer":"它解决总体准确相同的系统谁更能识别自己会错。","evidence":"两个准确率都是 80% 的助手"},"inputOutput":{"answer":"输入答案分数和标签，输出分组概率匹配判断。","evidence":"输入一组任务答案、模型分数和最终正确标签"},"mechanism":{"answer":"将相同分数样本分组并比较长期正确频率。","evidence":"0.8 是否长期约对应 80% 正确"},"interpretation":{"answer":"准确率区分度和校准分别衡量数量排序和数值含义。","evidence":"三者不是一回事"},"boundary":{"answer":"恒报基准率可能校准却不能用于风险分流。","evidence":"没有分流价值"}},{"section":2,"definition":{"answer":"原始置信信号是尚未拥有任务正确概率含义的风险分数。","evidence":"输出一个尚未具备概率含义的风险分数"},"problem":{"answer":"它解决模型自述与 token 概率是否能直接当正确率。","evidence":"都不能直接解释为答案正确概率"},"inputOutput":{"answer":"输入概率采样自评证据验证器和分歧，输出原始分数。","evidence":"输入 token 概率、多次采样、模型自评、检索覆盖、外部验证器和模型分歧"},"mechanism":{"answer":"在独立校准集学习分数到明确任务事件频率的映射。","evidence":"学习该分数到任务正确频率的映射"},"interpretation":{"answer":"映射后的数值只对应已定义的任务正确事件。","evidence":"任务事件可以是“退款资格正确且引用支持”"},"boundary":{"answer":"平均 token 概率和自信措辞都不是天然正确概率。","evidence":"平均 token 概率和“我很确定”的措辞"}},{"section":3,"definition":{"answer":"可靠性图和 ECE 检查置信承诺与实际正确频率。","evidence":"输出可靠性图与期望校准误差 ECE"},"problem":{"answer":"它解决一批零到一分数是否名副其实的问题。","evidence":"怎样检查一批 0 到 1 的分数"},"inputOutput":{"answer":"输入预测分桶置信和准确，输出图与 ECE。","evidence":"输入 n 个预测、分桶 Bm、每桶平均置信 conf(Bm)"},"mechanism":{"answer":"逐桶求绝对差并按样本占比加权求和。","evidence":"再乘该桶样本占比 |Bm|/n 并求和"},"interpretation":{"answer":"较小 ECE 只表示当前分桶下平均差距较小。","evidence":"当前分桶下平均差距越小"},"boundary":{"answer":"桶边界和切片可掩盖失准，不能机械跨设置比较。","evidence":"不能跨不同分桶机械比较"}},{"section":4,"definition":{"answer":"ECE 数值案例把十笔退款按低中高置信分桶计算。","evidence":"输出低中高三桶贡献与总 ECE"},"problem":{"answer":"它暴露高分组实际错误率远高于分数声称。","evidence":"高桶平均置信 0.90 却只正确 2/3"},"inputOutput":{"answer":"输入十笔分数与标签，输出桶贡献和总误差。","evidence":"输入十笔退款的分数和正确标签"},"mechanism":{"answer":"分别得到三桶加权差并相加为约零点一二。","evidence":"低桶贡献 0.010，中桶 0.040，高桶 0.070"},"interpretation":{"answer":"高桶过度自信说明原零点七阈值并不安全。","evidence":"原阈值会放行大量高成本错误"},"boundary":{"answer":"十个样本只演示算法，不能作为精确生产估计。","evidence":"不能把 0.120 当精确生产估计"}},{"section":5,"definition":{"answer":"温度缩放是在不改排序下重标度分类概率的后处理。","evidence":"输出 softmax(z/T) 的重标度概率"},"problem":{"answer":"它解决分类概率普遍过尖且过度自信的问题。","evidence":"软化过度尖锐分布"},"inputOutput":{"answer":"输入 logits 校准标签和 T，输出重标度概率。","evidence":"输入分类 logits z、独立校准标签和温度 T"},"mechanism":{"answer":"选择最小化校准集负对数似然的温度。","evidence":"选择使校准集负对数似然最小的 T"},"interpretation":{"answer":"T 大于一软化概率且通常不改变 top1 类别。","evidence":"通常不改 top1 预测"},"boundary":{"answer":"它不创造知识，事件或分布变化后需重新验证。","evidence":"不创造缺失知识"}},{"section":6,"definition":{"answer":"选择性决策按校准阈值选择自动人工或拒绝。","evidence":"输出自动、转人工或拒绝以及期望成本 Cost(τ)"},"problem":{"answer":"它解决覆盖率和被自动处理样本风险如何取舍。","evidence":"覆盖也降低选择性风险"},"inputOutput":{"answer":"输入分数阈值成本容量和 SLA，输出动作和成本。","evidence":"输入校准分数、阈值 τ、错误成本 Cerror"},"mechanism":{"answer":"仅让过阈值样本自动并求各结果概率成本之和。","evidence":"按三类结果的概率乘成本并求和"},"interpretation":{"answer":"阈值升高通常减少自动覆盖同时降低错误风险。","evidence":"阈值升高通常降低覆盖"},"boundary":{"answer":"审核队列满不能成为绕过高风险门槛的理由。","evidence":"队列满时不能绕过高风险门槛"}},{"section":7,"definition":{"answer":"序列置信是受长度措辞和共享盲点影响的生成信号。","evidence":"输出经过任务定义的风险分数"},"problem":{"answer":"它解释每个 token 高概率为何整段仍可能幻觉。","evidence":"为什么整段答案仍可能是幻觉"},"inputOutput":{"answer":"输入 token 概率长度采样事件证据，输出任务风险分数。","evidence":"输入 token 条件概率、文本长度、语义采样、任务事件和外部证据"},"mechanism":{"answer":"针对资格引用工具业务状态分别定义并校准事件。","evidence":"分别校准资格、引用、工具和业务状态"},"interpretation":{"answer":"高序列概率可能只代表常见短措辞而非事实正确。","evidence":"平均 logprob 偏好常见短措辞"},"boundary":{"answer":"分布外和对抗输入可使映射失效，高置信不保安全。","evidence":"高置信不是安全证明"}},{"section":8,"definition":{"answer":"生产校准监控持续连接分数版本阈值决策和成熟标签。","evidence":"输出滚动 ECE、Brier、风险覆盖曲线"},"problem":{"answer":"它解决真实标签延迟时怎样发现校准随时间腐烂。","evidence":"真实正确标签常常延迟几天"},"inputOutput":{"answer":"输入分数版本阈值切片标签，输出指标和响应。","evidence":"输入原始分数、校准版本、阈值、决策、切片和延迟成熟标签"},"mechanism":{"answer":"冻结发布证据金丝雀抽查，标签成熟后分切片重算。","evidence":"标签成熟后按语言政策和长度重算"},"interpretation":{"answer":"代理只作预警，成熟标签才验证真实概率含义。","evidence":"代理信号只做早期预警"},"boundary":{"answer":"无代表性新标签时调温度不能恢复旧映射有效性。","evidence":"单纯调大温度不能恢复校准"}}]},"html":"\n        <div class=\"dd-goals\"><b>读完你应该能：</b>区分准确率、置信度与校准；手算可靠性分桶和 ECE；理解温度缩放与选择性风险；按错误成本设置转人工阈值。</div>\n        \n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">1</span>准确不等于知道自己何时会错<span class=\"dd-badge intuition\">直觉</span></h2><p class=\"dd-lead\">两个准确率都是 80% 的助手，为什么一个可能更安全？</p><p>助手 A 对所有回答都报 0.8；助手 B 对熟悉案例报 0.95，对政策冲突报 0.35。若两者总体都答对 80%，准确率相同，但 B 的分数若可信，就能把低置信案例转人工，在保留大部分自动化的同时降低错误。A 无法排序风险。</p><p>校准关心“报出的概率与实际频率是否匹配”，区分能力排序和概率含义。一个模型可以很会排序却普遍过度自信，也可以校准良好却准确率低——永远报基准正确率就可能校准，但毫无区分价值。</p><div class=\"dd-note\"><b>三件事：</b>准确率看答对多少；区分度看正确样本能否排在错误样本前；校准看分数数值能否解释为真实频率。</div><p>校准评估输入一组任务答案、模型分数和最终正确标签，输出“相同分数组的经验正确率是否匹配声称概率”的判断。准确率回答总体答对多少，区分度回答能否把对错排序，校准回答 0.8 是否长期约对应 80% 正确；三者不是一回事。永远报基准正确率可能校准却没有分流价值。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">2</span>LLM 的“置信度”从哪里来<span class=\"dd-badge eng\">信号</span></h2><p class=\"dd-lead\">模型说“我非常确定”和 token logprob，哪个才是概率？</p><p>二者都不是天然的任务正确率。可用答案 token 的 logprob、多个采样答案的语义一致性、模型自评、检索证据强度、外部验证器、模型集成分歧等构造原始分数。然后在独立校准集上学习“分数→经验正确率”的映射。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>信号</th><th>优势</th><th>核心盲区</th></tr></thead><tbody><tr><td>序列/选项 logprob</td><td>便宜、连续</td><td>受长度和措辞影响，不等于事实正确</td></tr><tr><td>自我报告</td><td>易提示</td><td>会模仿自信语气，缺少概率训练</td></tr><tr><td>多样本一致性</td><td>发现不稳定答案</td><td>同一盲点可一致地错</td></tr><tr><td>外部验证</td><td>连接证据或执行结果</td><td>验证器也有覆盖与错误</td></tr><tr><td>模型集成</td><td>反映认知分歧</td><td>成本高且模型可能同源</td></tr></tbody></table></div><p>退款助手可组合“政策证据是否召回、资格分类 margin、金额程序校验、回答采样分歧”形成分数；不能拿平均 token 概率直接声称“答案 93% 正确”。</p><p>原始置信信号输入 token 概率、多次采样、模型自评、检索覆盖、外部验证器和模型分歧，输出一个尚未具备概率含义的风险分数。再用独立校准集学习该分数到任务正确频率的映射；任务事件可以是“退款资格正确且引用支持”。平均 token 概率和“我很确定”的措辞都不能直接解释为答案正确概率。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">3</span>可靠性图把概率承诺变成可检验频率<span class=\"dd-badge math\">机制</span></h2><p class=\"dd-lead\">怎样检查一批 0 到 1 的分数是否名副其实？</p><p>把预测按置信度分桶，每桶比较平均置信度 <code>conf(Bm)</code> 与实际准确率 <code>acc(Bm)</code>。理想可靠性图落在 y=x 对角线；曲线在对角线下方表示过度自信，在上方表示保守。分桶会隐藏桶内结构，因此还应看连续校准方法和关键切片。</p><div class=\"dd-formula\"><math display=\"block\" aria-label=\"期望校准误差\"><mi>ECE</mi><mo>=</mo><munder><mo>∑</mo><mi>m</mi></munder><mfrac><mrow><mo>|</mo><msub><mi>B</mi><mi>m</mi></msub><mo>|</mo></mrow><mi>n</mi></mfrac><mo>×</mo><mo>|</mo><mi>acc</mi><mo>(</mo><msub><mi>B</mi><mi>m</mi></msub><mo>)</mo><mo>−</mo><mi>conf</mi><mo>(</mo><msub><mi>B</mi><mi>m</mi></msub><mo>)</mo><mo>|</mo></math></div><p>Brier 分数 <code>(p−y)²</code> 同时惩罚概率偏差和错误；负对数似然对“高置信却错误”惩罚更重。ECE 直观但依赖桶数和边界，不宜跨不同分桶设置机械比较。</p><div class=\"dd-note warn\"><b>校准是条件性的。</b>　总体对角线漂亮，中文、长订单或新政策切片仍可能严重过度自信；必须按会影响风险的条件分组。</div><p>可靠性评估输入 n 个预测、分桶 Bm、每桶平均置信 conf(Bm) 和实际准确率 acc(Bm)，输出可靠性图与期望校准误差 ECE。对每桶取置信与准确的绝对差，再乘该桶样本占比 |Bm|/n 并求和；ECE 越小表示当前分桶下平均差距越小。结果依赖桶边界且可能掩盖切片失准，不能跨不同分桶机械比较。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">4</span>运行示例：十笔退款怎样算 ECE<span class=\"dd-badge math\">逐步演算</span></h2><p class=\"dd-lead\">原始分数看似很高，分桶后会暴露什么？</p><figure class=\"dd-fig\"><svg viewBox=\"0 0 700 260\" role=\"img\" aria-label=\"三组置信度的可靠性图与转人工阈值\"><line x1=\"70\" y1=\"205\" x2=\"350\" y2=\"205\" stroke=\"#6b7484\"/><line x1=\"70\" y1=\"205\" x2=\"70\" y2=\"28\" stroke=\"#6b7484\"/><line x1=\"70\" y1=\"205\" x2=\"320\" y2=\"44\" stroke=\"#6b7484\" stroke-dasharray=\"5 4\"/><text x=\"204\" y=\"235\" text-anchor=\"middle\" class=\"svg-t\">平均置信度</text><text x=\"20\" y=\"115\" text-anchor=\"middle\" class=\"svg-t\" transform=\"rotate(-90 20 115)\">实际正确率</text><circle cx=\"125\" cy=\"151\" r=\"7\" fill=\"#4f9d78\"/><text x=\"125\" y=\"140\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">低桶 .30/.33</text><circle cx=\"222\" cy=\"98\" r=\"7\" fill=\"#d3a05a\"/><text x=\"222\" y=\"86\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">中桶 .65/.67</text><circle cx=\"308\" cy=\"98\" r=\"7\" fill=\"#c77b72\"/><text x=\"308\" y=\"86\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">高桶 .90/.67</text><path d=\"M375,45 L375,210\" stroke=\"#6b7484\"/><rect x=\"410\" y=\"48\" width=\"244\" height=\"48\" rx=\"8\" fill=\"#21252d\" stroke=\"#c77b72\"/><text x=\"532\" y=\"68\" text-anchor=\"middle\" class=\"svg-t\">阈值 τ=0.7：高桶自动回答</text><text x=\"532\" y=\"86\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">覆盖 30%，选择性风险 33%</text><rect x=\"410\" y=\"119\" width=\"244\" height=\"48\" rx=\"8\" fill=\"#21252d\" stroke=\"#4f9d78\"/><text x=\"532\" y=\"139\" text-anchor=\"middle\" class=\"svg-t\">校准后高桶映射到约 0.67</text><text x=\"532\" y=\"157\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">原阈值不再允许自动回答</text><text x=\"532\" y=\"198\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">校准修正概率含义，不会修正答案本身</text></svg><figcaption>图 1　高置信桶实际只答对三分之二，暴露过度自信；阈值必须基于校准后的风险而非原始分数。</figcaption></figure><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>桶</th><th>样本数</th><th>平均置信</th><th>正确数</th><th>准确率</th><th>加权差</th></tr></thead><tbody><tr><td>低</td><td>3</td><td>0.30</td><td>1</td><td>0.333</td><td>3/10×.033=.010</td></tr><tr><td>中</td><td>4</td><td>0.65</td><td>3</td><td>0.75</td><td>4/10×.10=.040</td></tr><tr><td>高</td><td>3</td><td>0.90</td><td>2</td><td>0.667</td><td>3/10×.233=.070</td></tr></tbody></table></div><p>ECE≈0.120。只有十个样本，估计很不稳定，不能因为小数算出来就认为精确。最重要的运营发现是：原始 0.9 桶约三分之一错误，若错误退款代价高，阈值 0.7 绝不安全。</p><p>ECE 案例输入十笔退款的分数和正确标签，输出低中高三桶贡献与总 ECE。计算规则是每桶的 |准确率−平均置信| 乘该桶样本占比，再把各桶贡献相加。低桶贡献 0.010，中桶 0.040，高桶 0.070，相加约 0.120；高桶平均置信 0.90 却只正确 2/3，说明原阈值会放行大量高成本错误。十个样本只用于演示计算，不能把 0.120 当精确生产估计。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">5</span>温度缩放修正尺度但不创造知识<span class=\"dd-badge math\">后处理</span></h2><p class=\"dd-lead\">不重新训练模型，怎样把普遍过尖的分类概率拉回现实？</p><p>分类 logits 为 z 时，温度缩放使用 <code>softmax(z/T)</code>，在独立校准集上选择 T 使负对数似然最小。T&gt;1 会软化分布、降低过度自信；T&lt;1 会变尖。它保持类别排序不变，因此通常不改变 top-1 准确率，只调整概率含义。</p><p>二分类也可用 Platt scaling；非线性失真可用 isotonic regression，但数据少时更易过拟合。对自由文本需先定义事件——例如“资格判断正确且引用支持”——再校准该事件的分数。没有明确标签，所谓 0.8 不知道指什么。</p><div class=\"dd-note warn\"><b>数据纪律：</b>训练集学模型，验证集调系统，校准集学概率映射，测试集评最终表现。用测试标签选温度会再次乐观偏置。</div><p>温度缩放输入分类 logits z、独立校准标签和温度 T，输出 softmax(z/T) 的重标度概率。选择使校准集负对数似然最小的 T；T 大于 1 会软化过度尖锐分布，且因类别排序不变通常不改 top1 预测。它只修分数尺度，不创造缺失知识；事件定义或分布改变后必须重新验证。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">6</span>选择性预测在覆盖率与风险之间取舍<span class=\"dd-badge eng\">决策</span></h2><p class=\"dd-lead\">校准后，怎样决定自动答、转人工还是拒绝？</p><p>设阈值 τ，只对分数 ≥τ 的样本自动回答。覆盖率是被自动处理的比例，选择性风险是这些样本中的错误率。随着阈值升高，覆盖通常下降、风险下降；应画完整风险—覆盖曲线，而不是只报某个方便阈值。</p><div class=\"dd-formula\"><math display=\"block\" aria-label=\"阈值策略的期望成本\"><mi>Cost</mi><mo>(</mo><mi>τ</mi><mo>)</mo><mo>=</mo><mi>Cerror</mi><mo>×</mo><mi>PerrorAuto</mi><mo>+</mo><mi>Cmanual</mi><mo>×</mo><mi>Pmanual</mi><mo>+</mo><mi>Creject</mi><mo>×</mo><mi>Preject</mi></math></div><p>若错误承诺退款成本 100、人工复核成本 4，那么即使人工很多也可能划算；若是低风险文案润色，错误成本低，阈值可放宽。阈值还受审核容量和 SLA 约束：队列满时不能悄悄自动放行高风险案例，应降级为延迟处理或明确拒绝。</p><p>对多阶段系统可分别设门：证据不足先补检索，金额校验失败转人工，权限冲突禁止动作。单一回答置信度不应覆盖所有风险来源。</p><p>选择性决策输入校准分数、阈值 τ、错误成本 Cerror、人工成本 Cmanual、拒绝成本 Creject、审核容量和 SLA，输出自动、转人工或拒绝以及期望成本 Cost(τ)。只有分数达到阈值才自动，阈值升高通常降低覆盖也降低选择性风险；按三类结果的概率乘成本并求和选可行点。队列满时不能绕过高风险门槛。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">7</span>序列概率、语义多样性与系统性高置信错误<span class=\"dd-badge intuition\">失败边界</span></h2><p class=\"dd-lead\">模型对每个 token 都很自信，为什么整段答案仍可能是幻觉？</p><p>序列概率是 token 条件概率的乘积，天然随长度缩小；平均 logprob 又会偏好常见、短和模板化措辞。事实真假可能只取决于一个实体或数字，而其 token 在语言上非常常见。多次采样都得到同一错误也可能只是训练数据和提示诱导的共享盲点。</p><p>因此要校准“任务事件”而不是文本流畅度：资格结论、引用蕴含、工具执行和最终业务状态分别有标签。分布外输入、新政策、检索索引切换和对抗提示会破坏旧映射；高置信不构成安全证明。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>失效</th><th>表象</th><th>应对</th></tr></thead><tbody><tr><td>长度偏差</td><td>短答案分数更高</td><td>长度归一并按任务定义事件</td></tr><tr><td>同源盲点</td><td>多次采样一致地错</td><td>外部证据、异构验证器</td></tr><tr><td>切片错配</td><td>总体校准，少数群体失准</td><td>分层可靠性与最小样本</td></tr><tr><td>分布漂移</td><td>旧阈值错误激增</td><td>监控并重新校准/降级</td></tr></tbody></table></div><p>序列置信分析输入 token 条件概率、文本长度、语义采样、任务事件和外部证据，输出经过任务定义的风险分数。序列概率会随长度相乘缩小，平均 logprob 偏好常见短措辞，多次采样也可能共享同一盲点；因此分别校准资格、引用、工具和业务状态。分布外输入或对抗提示会使旧映射失效，高置信不是安全证明。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">8</span>上线后怎样监控校准是否腐烂<span class=\"dd-badge eng\">运维</span></h2><p class=\"dd-lead\">真实正确标签常常延迟几天，系统怎样及时发现风险？</p><p>保存原始分数、校准版本、阈值、决策、任务切片和最终标签。即时使用代理信号，如证据缺失、工具失败、用户纠正和人工改判；标签成熟后重算 ECE、Brier 与风险—覆盖曲线。用滚动窗口和置信区间避免因少量波动频繁改阈值。</p><ol class=\"dd-steps\"><li>发布前在冻结集上选择阈值并记录预计覆盖/风险。</li><li>金丝雀阶段抽样人工复核自动通过案例，尤其是接近阈值者。</li><li>按语言、政策版本和输入长度监控，不能只看总体。</li><li>漂移或高置信错误超过预算时收紧阈值、回滚映射或暂停自动动作。</li></ol><p>重新校准需要新的代表性标签；仅把温度调大让仪表盘好看，不会恢复事件定义和数据分布的一致性。</p><p>生产监控输入原始分数、校准版本、阈值、决策、切片和延迟成熟标签，输出滚动 ECE、Brier、风险覆盖曲线及收紧、回滚或暂停动作。发布前冻结阈值证据，金丝雀抽查自动通过案例，标签成熟后按语言政策和长度重算；代理信号只做早期预警。没有新的代表性标签时，单纯调大温度不能恢复校准。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"reference\"><h2><span class=\"dd-n\">9</span>常见误区与概念依赖<span class=\"dd-badge intuition\">常见误区与学习路线</span></h2><p class=\"dd-lead\">校准回答“这个分数意味着多大经验风险”，而不是“模型终于不会错”。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>误区</th><th>更准确的理解</th></tr></thead><tbody><tr><td>准确率高就一定校准好</td><td>总体正确多不代表概率数值可信</td></tr><tr><td>模型说很确定就是高置信</td><td>自述是一个待校准信号</td></tr><tr><td>ECE 低说明所有切片安全</td><td>总体分桶可掩盖条件性失准</td></tr><tr><td>温度缩放能提高知识</td><td>它通常不改排序，只修概率尺度</td></tr><tr><td>拒答越多越安全</td><td>覆盖、漏报、人工容量和拒绝伤害需共同权衡</td></tr></tbody></table></div><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>层级</th><th>概念依赖与延伸学习</th></tr></thead><tbody><tr><td>先修</td><td>概率、softmax、logprobs、模型评测</td></tr><tr><td><b>本页核心</b></td><td>可靠性图、ECE/Brier、后处理校准、风险—覆盖</td></tr><tr><td>决策</td><td>人在回路、护栏、选择性分类、成本敏感决策</td></tr><tr><td>生产</td><td>可观测性、数据漂移、幻觉评测、模型路由</td></tr></tbody></table></div></section>\n        <section class=\"dd-sec\" data-section-role=\"synthesis\"><h2><span class=\"dd-n\">10</span>把因果链连起来<span class=\"dd-badge intuition\">综合</span></h2><p class=\"dd-lead\">这个概念怎样从问题一路连接到可验证的实践？</p><ol class=\"dd-chain\"><li>定义需要校准的正确事件</li><li>从模型/证据/验证器取得原始分数</li><li>在独立校准集学习概率映射</li><li>用可靠性与评分规则验收</li><li>按错误成本选择阈值</li><li>持续收集成熟标签并监控漂移</li></ol></section>\n        <section class=\"dd-sec\" data-section-role=\"assessment\"><h2><span class=\"dd-n\">11</span>误区与自测<span class=\"dd-badge intuition\">自测</span></h2><p class=\"dd-lead\">你能否不用背术语，解释它的机制、边界与验证方法？</p><div class=\"dd-quiz\"><ol><li>准确率与校准有什么区别？</li><li>为什么平均 token logprob 不等于事实正确率？</li><li>温度缩放通常改变 top-1 准确率吗？</li><li>选择性风险是什么？</li><li>总体 ECE 低为何仍需切片？</li><li>假设“不确定性与校准：让“80% 把握”真的约等于 80% 正确”在离线示例上表现正常、上线后核心结果却下降，你会怎样按输入、内部变换、输出反馈和适用边界定位问题？</li><li>如何为“不确定性与校准：让“80% 把握”真的约等于 80% 正确”设计一个最小对照实验，证明观察到的改善来自核心机制，而不是数据、提示、权限或评测口径同时变化？</li></ol></div><details class=\"dd-answers\"><summary>参考答案</summary><ol><li>准确率是总体答对比例；校准要求某置信组的分数匹配该组经验正确率。</li><li>它受长度和语言常见度影响，没有直接定义任务正确事件。</li><li>不改变类别排序，所以通常不改变，只调整概率尖锐度。</li><li>超过阈值、被系统自动处理的样本中的错误率。</li><li>不同群体的过度与不足自信可在总体中互相抵消。</li><li>先保存同一失败样本及环境，确认输入、权限和前置条件没有漂移；再记录关键中间状态，检查机制是否按本页描述完成变换；随后把原始输出与独立指标、人工终验对照；最后用边界样例和对照实验复测。只有定位到首次偏离预期的环节，才能判断应修改数据、机制、评测还是使用边界。</li><li>固定数据、模型版本、提示、权限、预算和评测，只改变一个与核心机制直接相关的因素，并在多个样本与随机种子上重复；同时保存中间状态和失败样本。若差异只在目标因素变化时稳定出现，才支持机制解释，否则应继续排查混杂变量。</li></ol></details></section>\n        <div class=\"dd-src\"><b>资料来源与改编说明</b><ul><li><a href=\"https://arxiv.org/abs/1706.04599\" target=\"_blank\" rel=\"noopener\">On Calibration of Modern Neural Networks</a>：温度缩放与现代网络校准</li><li><a href=\"https://arxiv.org/abs/2302.09664\" target=\"_blank\" rel=\"noopener\">Semantic Uncertainty</a>：生成任务的语义不确定性</li><li><a href=\"https://arxiv.org/abs/1705.08500\" target=\"_blank\" rel=\"noopener\">Selective Classification for Deep Neural Networks</a>：风险—覆盖与选择性预测</li><li><a href=\"https://arxiv.org/abs/2207.05221\" target=\"_blank\" rel=\"noopener\">Uncertainty Estimation for Language Models</a>：语言生成置信与校准综述</li></ul><div class=\"dd-src-date\">访问日期：2026-07-22</div></div>"};
